package net.civeira.phylax.feature.oauth.mfa.infrastructure.driven;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.SQLException;
import java.sql.Timestamp;
import java.time.Instant;

import javax.sql.DataSource;

import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.feature.oauth.mfa.domain.gateway.RecoveryCodeConsumptionGateway;

/**
 * Consumes a recovery code with a single conditional update over
 * {@code access_user_mfa_recovery_code}: only the update that finds {@code used_at} empty counts.
 */
@ApplicationScoped
@RequiredArgsConstructor
public class RecoveryCodeConsumptionSqlAdapter implements RecoveryCodeConsumptionGateway {

  private final DataSource source;

  @Override
  public boolean consume(String codeUid, String userUid) {
    String sql = "UPDATE access_user_mfa_recovery_code SET used_at = ?, version = version + 1"
        + " WHERE uid = ? AND user = ? AND used_at IS NULL";
    try (Connection conn = source.getConnection();
        PreparedStatement stat = conn.prepareStatement(sql)) {
      stat.setTimestamp(1, Timestamp.from(Instant.now()));
      stat.setString(2, codeUid);
      stat.setString(3, userUid);
      return stat.executeUpdate() == 1;
    } catch (SQLException ex) {
      throw new IllegalStateException("Unable to consume a recovery code", ex);
    }
  }
}
